@RunWith(MockitoJUnitRunner.class)
public class BuildGlobalNamespace_shouldTraverse_TriageGen2Test {

    private BuildGlobalNamespace buildGlobalNamespace;

    @Mock
    private NodeTraversal mockTraversal;

    @Mock
    private Node mockNode;

    @Mock
    private Node mockParent;

    @Mock
    private Node mockExternsRoot;

    @Mock
    private JSModule mockModule;

    @Mock
    private Scope mockScope;

    @Before
    public void setUp() {
        // We use a spy to access/set internal state if necessary, 
        // but since externsRoot is likely package-private or protected, 
        // we rely on the structure provided.
        buildGlobalNamespace = spy(new BuildGlobalNamespace());
    }

    @Test
    public void testShouldTraverse_WhenExternsRootIsNull() {
        // Setup
        when(mockTraversal.getModule()).thenReturn(mockModule);
        when(mockTraversal.getScope()).thenReturn(mockScope);

        // Execute
        boolean result = buildGlobalNamespace.shouldTraverse(mockTraversal, mockNode, mockParent);

        // Verify
        assertTrue(result);
        // Verify collect was called with correct params
        verify(buildGlobalNamespace).collect(mockModule, mockScope, mockNode);
    }

    @Test
    public void testShouldTraverse_WhenExternsRootMatchesNode() {
        // Using reflection or manual setup if externsRoot is accessible. 
        // Assuming for the sake of the test we can influence the state.
        // Since we cannot set externsRoot directly via constructor, 
        // we assume the class allows setting it or we mock the behavior.

        // In a real scenario, we'd use ReflectionTestUtils or similar to set the private field 'externsRoot'
        // For this test, let's assume we've set it via a setter or it's accessible.
        setExternsRoot(buildGlobalNamespace, mockExternsRoot);

        when(mockTraversal.getScope()).thenReturn(mockScope);
        when(mockTraversal.getModule()).thenReturn(mockModule);
        // n == externsRoot
        when(mockNode.equals(mockExternsRoot)).thenReturn(true); 
        // However, the code uses == (identity), so we must ensure they are the same instance
        Node sameNodeAsExterns = mockExternsRoot; 

        // Execute
        boolean result = buildGlobalNamespace.shouldTraverse(mockTraversal, sameNodeAsExterns, mockParent);

        // Verify
        assertTrue(result);
        verify(buildGlobalNamespace).collect(mockModule, mockScope, sameNodeAsExterns);
        // Since externsScope is internal, we verify the logic path was taken by checking if it didn't crash
    }

    @Test
    public void testShouldTraverse_WhenExternsRootExistsButNodeDoesNotMatch() {
        setExternsRoot(buildGlobalNamespace, mockExternsRoot);

        when(mockTraversal.getModule()).thenReturn(mockModule);
        when(mockTraversal.getScope()).thenReturn(mockScope);

        // n != externsRoot
        Node differentNode = spy(new Node());

        // Execute
        boolean result = buildGlobalNamespace.shouldTraverse(mockTraversal, differentNode, mockParent);

        // Verify
        assertTrue(result);
        verify(buildGlobalNamespace).collect(mockModule, mockScope, differentNode);
    }

    /**
     * Helper to set the private field externsRoot via reflection to ensure coverage.
     */
    private void setExternsRoot(BuildGlobalNamespace instance, Node root) {
        try {
            java.lang.reflect.Field field = BuildGlobalNamespace.class.getDeclaredField("externsRoot");
            field.setAccessible(true);
            field.set(instance, root);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
